# =============================================================================== --selftest (CPU, mock)
def _mock_module():
    """A 2-layer GLM-shaped mock: 5 MLA leaves per layer, `mlp.experts` carrying 3-D
    gate_up_proj/down_proj like Glm4MoeLiteNaiveMoe (modeling_glm4_moe_lite.py:405-415), 4 experts.
    Layer 0 dense when first_dense=1. Plus a MockStreamer that does exactly what ExpertStreamer
    does to the module tree (pop the Parameters, attach/detach slabs via layer hooks)."""
    import torch
    import torch.nn as nn
    import torch.nn.functional as F

    class MockExperts(nn.Module):
        def __init__(self, E, H, I):
            super().__init__()
            self.num_experts, self.hidden_dim, self.intermediate_dim = E, H, I
            self.gate_up_proj = nn.Parameter(torch.randn(E, 2 * I, H) * 0.2)
            self.down_proj = nn.Parameter(torch.randn(E, H, I) * 0.2)
            self.act_fn = F.silu
            self.config = {"mock": True}

        def forward(self, hs, top_k_index, top_k_weights):
            final = torch.zeros_like(hs)
            for e in range(self.num_experts):
                pos, tok = torch.where(top_k_index.t() == e)
                if tok.numel() == 0:
                    continue
                cs = hs[tok]
                gate, up = F.linear(cs, self.gate_up_proj[e]).chunk(2, dim=-1)
                dh = F.linear(self.act_fn(gate) * up, self.down_proj[e])
                final.index_add_(0, tok, dh * top_k_weights[tok, pos, None])
            return final

    class MockDense(nn.Module):
        """Glm4MoeLiteMLP: the shape both the layer-0 FFN and every shared expert have."""

        def __init__(self, H, I):
            super().__init__()
            self.gate_proj, self.up_proj, self.down_proj = nn.Linear(H, I), nn.Linear(H, I), nn.Linear(I, H)

        def forward(self, x):
            return self.down_proj(F.silu(self.gate_proj(x)) * self.up_proj(x))

    class MockMoE(nn.Module):
        """A MoE block with the DENSE pathways a real Glm4MoeLite MoE layer has: `shared_experts`
        (trainable, trunk-resident) beside the routed `experts` slab (streamed, never wrapped) and
        the `gate` router (frozen). The E5 surface targets only the first of the three."""

        def __init__(self, E, H, I, k=2, n_shared=1):
            super().__init__()
            self.gate = nn.Linear(H, E, bias=False)
            self.experts = MockExperts(E, H, I)
            self.shared_experts = MockDense(H, I * n_shared)
            self.k = k

        def forward(self, x):
            B, T, H = x.shape
            flat = x.reshape(-1, H)
            w, idx = torch.topk(torch.softmax(self.gate(flat), dim=-1), self.k, dim=-1)
            return (self.experts(flat, idx, w) + self.shared_experts(flat)).view(B, T, H)

    class MockAttn(nn.Module):
        def __init__(self, d):
            super().__init__()
            for n, i, o in attention_leaf_dims(d):
                setattr(self, n, nn.Linear(i, o, bias=False))
            self.d = d

        def forward(self, x):
            d = self.d
            q = self.q_b_proj(self.q_a_proj(x))
            kv = self.kv_a_proj_with_mqa(x)
            k = self.kv_b_proj(kv[..., :d["kv_lora_rank"]])
            n_nope = d["heads"] * d["qk_nope"]
            score = (q[..., :n_nope] * k[..., :n_nope]).sum(-1, keepdim=True)
            return self.o_proj(k[..., n_nope:] * torch.sigmoid(score))

    class MockLayer(nn.Module):
        def __init__(self, d, moe):
            super().__init__()
            self.self_attn = MockAttn(d)
            self.mlp = (MockMoE(d["n_experts"], d["hidden"], d["moe_intermediate"], d["top_k"],
                                d["n_shared"]) if moe
                        else MockDense(d["hidden"], d["intermediate"]))

        def forward(self, h):
            h = h + self.self_attn(h)
            return h + self.mlp(h)

    class MockInner(nn.Module):
        def __init__(self, d, vocab):
            super().__init__()
            self.embed_tokens = nn.Embedding(vocab, d["hidden"])
            self.layers = nn.ModuleList([MockLayer(d, L >= d["first_dense"]) for L in range(d["n_layers"])])
            self.norm = nn.LayerNorm(d["hidden"])

    class MockGLM(nn.Module):
        def __init__(self, d, vocab=32):
            super().__init__()
            self.config = d
            self.model = MockInner(d, vocab)
            self.lm_head = nn.Linear(d["hidden"], vocab, bias=False)

        def forward(self, input_ids):
            h = self.model.embed_tokens(input_ids)
            for layer in self.model.layers:
                h = layer(h)
            return self.lm_head(self.model.norm(h))

    class MockStreamer:
        """ExpertStreamer's module-tree behaviour (glm_arc_eval.py:1015-1052): the expert Parameters
        are popped and replaced by None; a layer forward-pre-hook attaches the slab to
        `module.mlp.experts`, the post-hook detaches it."""

        def __init__(self, model, d):
            self.slabs, self.handles = {}, []
            for L in range(d["first_dense"], d["n_layers"]):
                dl = model.model.layers[L]
                e = dl.mlp.experts
                gu, dn = e.gate_up_proj.detach().clone(), e.down_proj.detach().clone()
                e._parameters.pop("gate_up_proj", None)
                e._parameters.pop("down_proj", None)
                e.gate_up_proj = None
                e.down_proj = None
                self.slabs[L] = (gu, dn)
                self.handles.append(dl.register_forward_pre_hook(self._pre(L)))
                self.handles.append(dl.register_forward_hook(self._post(L)))

        def _pre(self, L):
            def fn(module, args):
                exp = module.mlp.experts
                exp.gate_up_proj, exp.down_proj = self.slabs[L]
            return fn

        def _post(self, L):
            def fn(module, args, output):
                exp = module.mlp.experts
                exp.gate_up_proj = None
                exp.down_proj = None
            return fn

    return MockGLM, MockStreamer


def _glm47_dims():
    """GLM-4.7-Flash dims as read from D:/hf_models/GLM-4.7-Flash-bf16/config.json on 2026-09-11 --
    the selftest's stand-in when that config is not on this box (the numbers must still derive)."""
