class _DLSlowSnapMem(_ReplMem):
    """Review F2's relay: every snapshot PUT (a chunk or its manifest) takes `delay` s; the first PUT time of every name
    is recorded."""

    def __init__(self, delay):
        _ReplMem.__init__(self)
        self.delay, self.t_put = float(delay), {}

    def put(self, data, name, retries=1):
        if "/snap/" in name:
            time.sleep(self.delay)
        sha = _ReplMem.put(self, data, name, retries)
        self.t_put.setdefault(name, time.time())
        return sha

    def put_write_once(self, data, name):
        sha = _ReplMem.put_write_once(self, data, name)
        self.t_put.setdefault(name, time.time())
        return sha


def _selftest_diloco_review(a, ok, quiet):
    """The review fixes of 2026-10-08 (F1 closer-level, F2, F3, F5): each check fails on runner 941c1d7f."""
    import shutil
    np = _repl_np()
    # (d-closer-resume) F1 through the closer itself: a fleet paused after round 1 (item 15); the closer is restarted
    # with its clock 40,000 s later and NO node has rejoined yet: it must WAIT (idle runs from its own start), then
    # STOP only idle_s (3 s) after its start
    mem = _ReplMem()
    noon = time.mktime((2026, 10, 8, 12, 0, 0, 0, 0, -1))
    nds, ccp, erp, tmp, _e = _dl_toy(3, 3, mem, "t/dl_f1", H=2, dp_over={"idle_s": 3.0},
                                     closer_kw={"pause_at": "11:00", "local_clock": (lambda: noon)})
    try:
        later = (lambda: time.time() + 40000.0)
        res, lines = {}, []
        t0 = time.time()

        def rerun():
            res["code"] = dl_closer_run(mem, "t/dl_f1", 3, os.path.join(tmp, "closer"), lines.append, poll_s=0.01,
                                        clock=later, start_wait_s=10.0)
            res["t"] = time.time() - t0
        th = threading.Thread(target=rerun, daemon=True)
        th.start()
        time.sleep(1.0)
        early = dict(_dl_ctl(mem, "t/dl_f1"))
        th.join(30.0)
        s1 = str(_dl_ctl(mem, "t/dl_f1").get("stop", {}).get("reason"))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    ok("(d-closer-resume) review F1, closer level: paused after k0001; the closer restarted 40,000 s later publishes "
       "NOTHING in its first second (the old rule STOPped on its first poll), then the idle STOP only idle_s after ITS "
       "start (code 4)",
       ccp == 4 and all(isinstance(erp.get(x), DLPause) for x in "ABC") and not early and res.get("code") == 4
       and "no valid part of round 2" in s1 and res.get("t", 0) >= 2.9,
       "first run %s; restarted: early %s, code %s after %.1f s: %s" % (ccp, sorted(early), res.get("code"),
                                                                         res.get("t", -1), s1[:90]))
    # (d-snap-bg) F2: A (the first included node) PUTs theta_0 in the background: a 1.5 s-per-PUT snapshot store never
    # delays A's next round; a second snapshot while one is in flight is SKIPPED; z0001 lands with the agreed d_1
    mem = _DLSlowSnapMem(1.5)
    nds, ccs, ers, tmp, _e = _dl_toy(3, 3, mem, "t/dl_f2", H=2)
